this.getCurrentOutputSettings = function ( vanillaOutputBoxNodeOrSelector ) {
            const vanillaOutputBoxNode = vanillaOutputBoxNodeOrSelector.nodeName ? vanillaOutputBoxNodeOrSelector : document.querySelector(vanillaOutputBoxNodeOrSelector);
            const currentOutputSettings = {};
            if ( vanillaOutputBoxNode ) {
                const wasSuccessful = _addOutputControlValues( vanillaOutputBoxNode, currentOutputSettings );
                console.debug('Collected output settings:', currentOutputSettings);
                return wasSuccessful ? currentOutputSettings : null;
            } else {
                return currentOutputSettings;
            }
        };
